// propagate carries
static spint inline prop(spint *n) {
  int i;
  spint mask = ((spint)1 << 59u) - (spint)1;
  sspint carry = (sspint)n[0];
  carry >>= 59u;
  n[0] &= mask;
  for (i = 1; i < 277; i++) {
    carry += (sspint)n[i];
    n[i] = (spint)carry & mask;
    carry >>= 59u;
  }
  n[277] += (spint)carry;
  return -((n[277] >> 1) >> 62u);
}

