// Convert n back to normal form, m=redc(n)
static void redc(const spint *n, spint *m) {
  int i;
  spint c[278];
  c[0] = 1;
  for (i = 1; i < 278; i++) {
    c[i] = 0;
  }
  modmul(n, c, m);
  (void)modfsb(m);
}

// is unity?
static int modis1(const spint *a) {
  int i;
  spint c[278];
  spint c0;
  spint d = 0;
  redc(a, c);
  for (i = 1; i < 278; i++) {
    d |= c[i];
  }
  c0 = (spint)c[0];
  return ((spint)1 & ((d - (spint)1) >> 59u) &
          (((c0 ^ (spint)1) - (spint)1) >> 59u));
}

// is zero?
static int modis0(const spint *a) {
  int i;
  spint c[278];
  spint d = 0;
  redc(a, c);
  for (i = 0; i < 278; i++) {
    d |= c[i];
  }
  return ((spint)1 & ((d - (spint)1) >> 59u));
}

// set to zero
static void modzer(spint *a) {
  int i;
  for (i = 0; i < 278; i++) {
    a[i] = 0;
  }
}

// set to one
static void modone(spint *a) {
  int i;
  a[0] = 1;
  for (i = 1; i < 278; i++) {
    a[i] = 0;
  }
  nres(a, a);
}

// set to integer
static void modint(int x, spint *a) {
  int i;
  a[0] = (spint)x;
  for (i = 1; i < 278; i++) {
    a[i] = 0;
  }
  nres(a, a);
}

